// Files are generated by a real DuckDB instance, not the MO encoder. This is
// opt-in because installing independent engines is not a unit-test dependency.
func TestParquetVariantDuckDBInstance(t *testing.T) {
	dir := os.Getenv("MO_VARIANT_INTEROP_DIR")
	if dir == "" {
		t.Skip("set MO_VARIANT_INTEROP_DIR to independent-engine fixtures")
	}
	for _, kind := range []string{"automatic", "shredded"} {
		t.Run(kind, func(t *testing.T) {
			data, e := os.ReadFile(filepath.Join(dir, "duckdb-"+kind+".parquet"))
			require.NoError(t, e)
			param := nestedAndScalarProjectionParam(data)
			param.Cols[1].Typ.Id = int32(types.T_json)
			proc := testutil.NewProc(t)
			r := NewParquetReader(param, proc)
			empty, e := r.Open(param, proc)
			require.NoError(t, e)
			require.False(t, empty)
			defer r.Close()
			seen := 0
			done := false
			for !done {
				b := vectorBatch([]types.Type{types.T_int32.ToType(), types.T_json.ToType()})
				done, e = r.ReadBatch(context.Background(), b, proc, nil)
				require.NoError(t, e)
				for row := 0; row < b.RowCount(); row++ {
					got := types.DecodeJson(b.Vecs[1].GetBytesAt(row))
					drift := fmt.Sprint(seen)
					if seen%11 == 0 {
						drift = "null"
					}
					expected, e := bytejson.ParseFromStringExact(fmt.Sprintf(`{"trace_id":"trace-%d","cost":9007199254740993.%03d,"latency":%d,"drift":%s,"nested":{"ok":%t,"tags":["agent","tool"]}}`, seen, seen%1000, seen%997, drift, seen%2 == 0))
					require.NoError(t, e)
					require.Zero(t, bytejson.CompareByteJson(expected, got), "row=%d expected=%s got=%s", seen, expected.String(), got.String())
					p, e := bytejson.ParseJsonPath("$.cost")
					require.NoError(t, e)
					value, ok := got.QuerySimpleExist(&p)
					require.True(t, ok)
					require.Equal(t, bytejson.TpCodeDecimal, value.Type)
					require.Equal(t, fmt.Sprintf("9007199254740993.%03d", seen%1000), value.String())
					seen++
				}
				b.Clean(proc.Mp())
			}
			require.Equal(t, 10000, seen)
		})
	}
}

// Doris 4.0.3 exports its native VARIANT as a UTF8 JSON string, not Parquet
// VARIANT. Compare against what the Doris instance returned, preserving its
// observed null/boolean conversion in the fixture without asserting source
// identities survived ingestion into Doris.
func TestParquetDorisInstanceExport(t *testing.T) {
	dir := os.Getenv("MO_VARIANT_INTEROP_DIR")
	if dir == "" {
		t.Skip("independent Doris fixtures required")
	}
	matches, e := filepath.Glob(filepath.Join(dir, "doris-bridge-*.parquet"))
	require.NoError(t, e)
	require.Len(t, matches, 1)
	data, e := os.ReadFile(matches[0])
	require.NoError(t, e)
	expectedBytes, e := os.ReadFile(filepath.Join(dir, "doris-bridge-actual.json"))
	require.NoError(t, e)
	var expected []struct {
		ID  int             `json:"a_unused_000"`
		Doc json.RawMessage `json:"z_nested"`
	}
	require.NoError(t, json.Unmarshal(expectedBytes, &expected))
	param := nestedAndScalarProjectionParam(data)
	param.Cols[0].Typ.NotNullable = false
	param.Cols[1].Typ.Id = int32(types.T_json)
	proc := testutil.NewProc(t)
	r := NewParquetReader(param, proc)
	empty, e := r.Open(param, proc)
	require.NoError(t, e)
	require.False(t, empty)
	defer r.Close()
	seen := 0
	done := false
	for !done {
		b := vectorBatch([]types.Type{types.T_int32.ToType(), types.T_json.ToType()})
		done, e = r.ReadBatch(context.Background(), b, proc, nil)
		require.NoError(t, e)
		for row := 0; row < b.RowCount(); row++ {
			id := vector.GetFixedAtNoTypeCheck[int32](b.Vecs[0], row)
			want, e := bytejson.ParseFromByteSliceExact(expected[id].Doc)
			require.NoError(t, e)
			got := types.DecodeJson(b.Vecs[1].GetBytesAt(row))
			require.Zero(t, bytejson.CompareByteJson(want, got), "Doris row %d", id)
			seen++
		}
		b.Clean(proc.Mp())
	}
	require.Equal(t, 10000, seen)
}
